// Franc.js - Language detection library
// Simplified version for Chrome extension
(function(global) {
    'use strict';
    
    var franc = function(text) {
        if (!text || typeof text !== 'string') return 'und';
        
        var patterns = {
            'vi': /[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]/i,
            'en': /^[a-zA-Z0-9\s.,!?;:'"\-()]+$/,
            'es': /[ñáéíóúüç]/i,
            'fr': /[àâäéèêëïîôöùûüÿç]/i,
            'zh': /[\u4e00-\u9fff]/,
            'ja': /[\u3040-\u309f\u30a0-\u30ff]/,
            'ko': /[\uac00-\ud7af]/,
            'ar': /[\u0600-\u06ff]/,
            'th': /[\u0e00-\u0e7f]/
        };
        
        var scores = {};
        Object.keys(patterns).forEach(function(lang) {
            scores[lang] = 0;
            var matches = text.match(patterns[lang]);
            if (matches) {
                scores[lang] = matches.length;
            }
        });
        
        var maxScore = 0;
        var detectedLang = 'en';
        Object.entries(scores).forEach(function([lang, score]) {
            if (score > maxScore) {
                maxScore = score;
                detectedLang = lang;
            }
        });
        
        return detectedLang;
    };
    
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = franc;
    } else {
        global.franc = franc;
    }
})(typeof window !== 'undefined' ? window : this);
